<?php $page_title='Peninjauan produk'; $this->load->view('staff/_layout_start',compact('user','page_title')); ?>
<section class="staff-hero"><div><span class="staff-kicker">ETALASE</span><h1>Peninjauan produk</h1><p>Periksa produk sebelum diterbitkan di etalase.</p></div></section>
<?php if ($this->input->get('tersimpan')): ?><div class="alert alert-success">Keputusan berhasil disimpan.</div><?php endif; ?>
<section class="staff-panel">
  <form class="staff-list-filter" method="get"><label>Cari<input class="form-control" type="search" name="q" maxlength="80" value="<?= html_escape($search) ?>" placeholder="Produk atau toko"></label><label>Status<select class="form-select" name="status"><?php foreach(array('pending'=>'Menunggu','approved'=>'Disetujui','rejected'=>'Ditolak','cancelled'=>'Dibatalkan') as $value=>$label): ?><option value="<?= $value ?>" <?= $status===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><?php $this->load->view('staff/_list_size',array('per_page'=>$per_page)); ?><button type="submit">Terapkan</button></form>
  <p class="staff-list-count"><?= number_format($total,0,',','.') ?> pengajuan</p>
  <?php if (!$rows): ?><p>Belum ada pengajuan pada status ini.</p><?php endif; ?>
  <div class="catalog-list"><?php foreach($rows as $row): ?><article class="staff-panel"><h3><a href="<?= site_url('pengelola/produk/'.$row['product_id']) ?>"><?= html_escape($row['name']) ?></a></h3><p><?= html_escape($row['store_name'].' · '.$row['requester_name'].' · '.$row['created_at']) ?></p><?php if ($row['decision_note']): ?><p><?= html_escape($row['decision_note']) ?></p><?php endif; ?><?php if ($row['status']==='pending'): ?><form method="post" action="<?= site_url('pengelola/tinjauan-produk/'.$row['id'].'/putusan') ?>"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><label class="form-label">Alasan keputusan<textarea class="form-control" name="decision_note" minlength="10" maxlength="500" required rows="2"></textarea></label><button class="btn btn-primary" type="submit" name="decision" value="approved">Setujui</button> <button class="btn btn-outline-danger" type="submit" name="decision" value="rejected">Tolak</button></form><?php endif; ?></article><?php endforeach; ?></div>
  <?php $this->load->view('staff/_pagination',array('base'=>site_url('pengelola/tinjauan-produk'),'params'=>array('q'=>$search,'status'=>$status,'per_page'=>$per_page),'page'=>$page,'pages'=>$pages)); ?>
</section>
<?php $this->load->view('staff/_layout_end'); ?>
